hydrator:
const data=bundledPrecomputedData();
if(!data)return false;
let hydrated=false;
try{
  // 노선 좌표는 기존 v65 캐시를 그대로 재사용합니다. v66은 수거권역 구조만 변경합니다.
  if(data.version===DONG_ROUTE_CACHE_VERSION){
    const specMap=new Map(allDongRouteSpecs().map(s=>[`${s.type}|${s.vehicle}|${s.day}`,s]));
    for(const r of (data.routes||[])){
      const spec=specMap.get(`${r.type}|${r.vehicle}|${r.day}`);
      if(!spec||existingDongRouteOverlay(spec))continue;
      createDongRouteOverlay(spec,{...(r.data||{}),fromCache:true,fromBundle:true});
    }
    hydrated=true;
  }
  // v65의 잘게 쪼갠 읍·면 권역은 v66에서 절대 복원하지 않습니다.
  if(data.zoneVersion===SERVICE_ZONE_CACHE_VERSION){
    for(const type of ['general','recycle']){
      const zones=Array.isArray(data.zones?.[type])?data.zones[type]:[];
      if(zones.length){
        clearServiceZoneOverlays(type);
        for(const z of zones)addServiceZonePolygon(type,z.points,{...z,automatic:true,fromCache:true,fromBundle:true});
        rebuildManualZoneOverlays(type);
        serviceZoneBuilt[type]=true;
        serviceZoneCacheHydrated[type]=true;
        hydrated=true;
      }
    }
  }
  return hydrated;
}catch(e){console.warn('내장 사전계산 데이터 복원 실패',e);return false}
